# Fix: filter out default-class <position> elements (those without a "joint" attr)
actuators = []
for a in root.iter("position"):
    name = a.get("name")
    jnt  = a.get("joint")
    if name is None or jnt is None:
        continue   # skip default-class entries
    cr = None
    for j in named_joints:
        if j["name"] == jnt:
            cr = j["ctrlrange"]
            break
    actuators.append({"name": name, "joint": jnt, "ctrlrange": cr})
    print(f"  actuator: {name:<12s}  joint={jnt:<10s}  ctrlrange={cr}")

print(f"\nTotal actuators: {len(actuators)}")

# ── Sites ────────────────────────────────────────────────────────────────────
sites = []
for s in root.iter("site"):
    sites.append({"name": s.get("name"), "pos": s.get("pos")})
print("\nSites:", sites)

# ── Equality constraints ──────────────────────────────────────────────────────
equalities = []
for eq in root.iter("joint"):
    pass  # already done above
for eq in root.find("equality").iter() if root.find("equality") is not None else []:
    if eq.tag == "joint":
        equalities.append({"joint1": eq.get("joint1"), "joint2": eq.get("joint2"),
                           "polycoef": eq.get("polycoef")})
print("Equalities:", equalities)

# ── Free-joint bodies (graspable) ─────────────────────────────────────────────
free_bodies = []
for b in root.iter("body"):
    for j in b.findall("joint"):
        if j.get("type") == "free":
            free_bodies.append(b.get("name"))
print("Free-joint bodies:", free_bodies)
